program='''from collections import defaultdict


def _components(grid, background):
    height, width = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                point = stack.pop()
                cells.append(point)
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = point[0] + dr, point[1] + dc
                    if (0 <= nr < height and 0 <= nc < width and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            r0 = min(r for r, _ in cells)
            c0 = min(c for _, c in cells)
            r1 = max(r for r, _ in cells)
            c1 = max(c for _, c in cells)
            shape = tuple(sorted((r - r0, c - c0) for r, c in cells))
            components.append({
                "color": color, "cells": cells, "shape": shape,
                "box": (r0, c0, r1, c1),
            })
    return components


def _l_corners(component):
    r0, c0, r1, c1 = component["box"]
    if r0 == r1 or c0 == c1:
        return []
    cells = set(component["cells"])
    corners = []
    for r in (r0, r1):
        for c in (c0, c1):
            expected = ({(r, x) for x in range(c0, c1 + 1)} |
                        {(x, c) for x in range(r0, r1 + 1)})
            if cells == expected:
                corners.append((r, c))
    return corners


def transform(grid):
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)
    components = _components(grid, background)

    selectors = []
    for i, component in enumerate(components):
        for corner in _l_corners(component):
            selectors.append((len(component["cells"]), i, corner))
    if not selectors:
        return [row[:] for row in grid]
    _, selector_i, (corner_r, corner_c) = max(selectors)
    selector = components[selector_i]
    r0, c0, r1, c1 = selector["box"]
    row_direction = 1 if corner_r == r0 else -1
    col_direction = 1 if corner_c == c0 else -1

    def inside_open_corner(component):
        a, b, x, y = component["box"]
        center_r = (a + x) / 2
        center_c = (b + y) / 2
        return ((center_r - corner_r) * row_direction > 0 and
                (center_c - corner_c) * col_direction > 0)

    by_shape = defaultdict(list)
    for i, component in enumerate(components):
        if i != selector_i:
            by_shape[component["shape"]].append(i)

    candidates = []
    for indices in by_shape.values():
        for p in range(len(indices)):
            for q in range(p + 1, len(indices)):
                first, second = indices[p], indices[q]
                first_inside = inside_open_corner(components[first])
                second_inside = inside_open_corner(components[second])
                if first_inside != second_inside:
                    candidates.append(second if first_inside else first)

    if len(candidates) != 1:
        return [row[:] for row in grid]

    output = [row[:] for row in grid]
    target = components[candidates[0]]
    for r, c in target["cells"]:
        output[r][c] = selector["color"]
    return output
'''
